CREATE TABLE IF NOT EXISTS live_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NOT NULL DEFAULT current_setting('hatchable.user_id', true), idempotency_key text NOT NULL, campaign_id uuid NULL, leg_id text NULL, instrument_key text NOT NULL, transaction_type text NOT NULL, quantity integer NOT NULL, requested_payload jsonb NOT NULL DEFAULT '{}'::jsonb, broker_order_id text NULL, status text NOT NULL DEFAULT 'CREATED', filled_quantity integer NOT NULL DEFAULT 0, average_price numeric NULL, error_message text NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,idempotency_key))